//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gLastJob = "조회";
scwin.gToday = "";
scwin.gNextday = "";
scwin.gSearchDay = "";
scwin.gStatTp = 9; //1:미처리,2:1차검토,3:2차검토,9:승인
scwin.gStatCd = "";
scwin.gConfrmYn = "";
scwin.gConfrmRow = "";
scwin.gConfrmId = "";
scwin.vScrenID = 'ULDSTF41010.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetNextDay = function() {
    var url = "/PersonOnDuty.do?method=getNextDay" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Nextday.DataID = encodeURI(url);
    dts_Nextday.Reset();
};
scwin.fn_getToday = function() {
    var date_now = new Date();
    var y = date_now.getFullYear().toString();
    var m = (date_now.getMonth() + 1).toString().length == 1 ? "0" + (date_now.getMonth() + 1).toString() : (date_now.getMonth() + 1).toString();
    var d = date_now.getDate().toString().length == 1 ? "0" + date_now.getDate().toString() : date_now.getDate().toString();
    var h = date_now.getHours();
    if (h >= 13) {
        //13시 이후 다음날로 간주
        return scwin.gNextday;
    }
    return '' + y + m + d;
};
scwin.fn_getTime = function() {
    var date = new Date();
    var h = date.getHours().toString();
    var m = date.getMinutes().toString().length == 1 ? "0" + date.getMinutes().toString() : date.getMinutes().toString();
    var s = date.getSeconds().toString().length == 1 ? "0" + date.getSeconds().toString() : date.getSeconds().toString();
    return '' + h + m + s;
};
scwin.fn_SetInit = function() {
    $c.stf.setObjectValue(edt_Date, scwin.fn_getToday());
};
scwin.fn_SetInitMaster = function() {
    $c.stf.setObjectValue(txb_com_abbrv, '');
    //setObjectValue(cmb_DEP_CD, js_dep_cd);
    $c.stf.setObjectValue(cmb_EMP_NO, js_emp_no);
};
scwin.fn_SetCode = function() {
    dts_DIARY_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DUTY_DIARY_MKTACT_TP_CD";
    dts_DIARY_TP_CD.Reset();
    dts_EMP_NO.DataID = "/PersonOnDuty.do?method=listComboEmpNo&For=C&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();

    //dts_DEP_CD.DataID = "/PersonOnDuty.do?method=listComboDepCd&inputMessageId=CODE_EMPDEP_IN&For=C&DEP_CD=" + gDepCd;
    dts_DEP_CD.DataID = "/PersonOnDuty.do?method=listComboDepCd&For=C&EMP_NO=" + scwin.gEmpNo;
    dts_DEP_CD.Reset();
};
scwin.fn_getMsgInnerHtml = function(msg, k) {
    var text1 = "";
    if (k == 0) {
        text1 = "        <td align='center' width='10' style='padding-left:20px'><a href='javascript:fn_InitProcsStat();'><img src='../img/btn_cancel.gif' name='procs_init_btn' style='border:none;'></a></td>";
    }
    var text = "    <tr style='height:20px;'>" + "        <td align='left' width='2%' nowrap><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + msg + "</span></td>" + text1 + "    </tr>";
    return text;
};
scwin.fn_getBtnInnerHtml = function(tp, cd) {
    var btn_nm = tp == 3 ? 'approval' : 'study' + tp;
    scwin.gStatTp = tp;
    scwin.gStatCd = cd;
    var text = "    <tr>" +
        //						"        <td align='center' width='10'><input type='image' src='../img/btn_"+ btn_nm + ".gif' onclick='javascript:fn_SaveProcsStat(" + cd + ");'/></td>" +
        "        <td align='center' width='10'><a  href='javascript:fn_ReadDutyDiaryTranstr();'><img src='../img/btn_" + btn_nm + ".gif' name='procs_btn' style='border:none;'></a></td>" + "    </tr>";
    return text;
};
scwin.fn_DrawDiaryProcsStat = function() {
    panel_2.innerHTML = '';
    var sUpdateCd = dts_Procs.getCellData(1, "NEXT_PROCS_STAT_CD");
    var table = "<table border='0' cellpadding='2' cellspacing='0' height='22' width='100%' style='margin-left:5px;margin-top:3px;'>";
    var k = 0;
    for (var i = 1; i <= 3; i++) {
        if (dts_Procs.getCellData(1, "MSG" + i) == '') {
            table += scwin.fn_getBtnInnerHtml(i, sUpdateCd);
            i = 4;
        } else {
            table += scwin.fn_getMsgInnerHtml(dts_Procs.getCellData(1, "MSG" + i), k++);
        }
    }
    table += "</table>";
    panel_2.innerHTML = table;
};
scwin.fn_InitProcsStat = function() {
    if (!scwin.fn_validDateTodayCheck()) {
        return;
    }
    var aProcsNm = new Array();
    aProcsNm[1] = "미처리";
    aProcsNm[2] = "1차 검토";
    aProcsNm[3] = "2차 검토";
    aProcsNm[9] = "승인";

    //alert(aProcsNm[gStatTp]);

    var vAnswer = confirm(aProcsNm[scwin.gStatTp] + ' 취소하시겠습니까?');
    if (vAnswer == true) {
        dts_UpdateProcs.setCellData(1, "CONFRM_DD", scwin.gSearchDay);
        dts_UpdateProcs.setCellData(1, "MSG4", scwin.fn_getTime());
        scwin.gLastJob = "취소";
        trs_UpdateProcs.Action = "/PersonOnDuty.do?method=initDutyDiaryProcsStat&CONFRM_DD=" + scwin.gSearchDay + "&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_UpdateProcs.KeyName = "toinb_dataid4";
        trs_UpdateProcs.KeyValue = "JSP(I:pInput=dts_UpdateProcs)";
        trs_UpdateProcs.Post();
    }
};
scwin.fn_SaveProcsStat = function() {
    if (!scwin.fn_validDateTodayCheck()) {
        return;
    }
    var sProcsNm = scwin.gStatTp == 3 ? '승인' : scwin.gStatTp + '차 검토';
    var sEmpNm = dts_Transtr.getCellData(1, "EMP_NM" + scwin.gStatTp);
    var sProcsDdtm = dts_Transtr.getCellData(1, "PROCS_DDTM" + scwin.gStatTp);
    if (sProcsDdtm.length > 0) {
        $c.win.alert(sEmpNm + "님에 의해 처리되었습니다. (" + sProcsDdtm + ")");
        scwin.fn_ReadProcsStat();
        return;
    }
    dts_UpdateProcs.setCellData(1, "CONFRM_DD", scwin.gSearchDay);
    dts_UpdateProcs.setCellData(1, "DUTY_DIARY_PROCS_STAT_CD", scwin.gStatCd);
    dts_UpdateProcs.setCellData(1, "MSG4", scwin.fn_getTime());
    scwin.gLastJob = sProcsNm;
    trs_UpdateProcs.Action = "/PersonOnDuty.do?method=updateDutyDiaryProcsStat&CONFRM_DD=" + scwin.gSearchDay + "&DUTY_DIARY_PROCS_STAT_CD=" + scwin.gStatCd + "&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_UpdateProcs.KeyName = "toinb_dataid4";
    trs_UpdateProcs.KeyValue = "JSP(I:pInput=dts_UpdateProcs)";
    trs_UpdateProcs.Post();
};


//검토/승인 되었는지 확인
scwin.fn_ReadDutyDiaryTranstr = function() {
    if (!scwin.fn_validDateTodayCheck() || !scwin.fn_validConfrmCheck()) {
        return;
    }
    var sProcsNm = scwin.gStatTp == 3 ? '승인' : scwin.gStatTp + '차 검토';
    var sNm1 = '\n' + sProcsNm + ' 후에는 당번일지 수정이 불가합니다.';
    var vAnswer = confirm(sProcsNm + '처리 하시겠습니까?' + (scwin.gStatTp == 2 ? sNm1 : ''));
    if (vAnswer == true) {
        var url = "/PersonOnDuty.do?method=readDutyDiaryTranstr" + "&CONFRM_DD=" + scwin.gSearchDay + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Transtr.DataID = encodeURI(url);
        dts_Transtr.Reset();
    }
};
scwin.fn_SaveMktact = function() {
    var diary_tp_cd = dts_MASTER.getCellData(1, "DUTY_DIARY_MKTACT_TP_CD");
    var isur_cd = dts_MASTER.getCellData(1, "ISUR_CD");
    var contn = dts_MASTER.getCellData(1, "DUTY_DIARY_MKTACT_CONTN");
    var ref_contn = dts_MASTER.getCellData(1, "DUTY_DIARY_MKTACT_REF_CONTN");
    var dep_cd = dts_MASTER.getCellData(1, "DEP_CD");
    var dep_nm = dts_MASTER.getCellData(1, "DEP_NM");
    var emp_no = dts_MASTER.getCellData(1, "EMP_NO");

    //alert(diary_tp_cd + "\n" + isur_cd + "\n" + contn + "\n" + ref_contn + "\n" + dep_cd + "\n" + dep_nm + "\n" + emp_no);

    if (!scwin.fn_validCheck() || !scwin.fn_validDateCheck()) {
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        trs_Save.Action = "/PersonOnDuty.do?method=saveDutyDiaryMktactDtl&CONFRM_DD=" + scwin.gSearchDay + "&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.Post();
    }
};
scwin.fn_ReadExistIsurCdYn = function() {
    var url = "/PersonOnDuty.do?method=readExistIsurCdYn" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_IsurCdYn.DataID = encodeURI(url);
    dts_IsurCdYn.Reset();
};
scwin.fn_SaveConfrm = function() {
    if (!scwin.fn_validDateCheck()) {
        return;
    }

    //수정되지 않은 데이터도 확인하기 위해
    for (var i = 1; i <= dts_Confrm.getTotalRow(); i++) {
        dts_Confrm.setCellData(i, "STAT", dts_Confrm.getRowStatus(i));
        dts_Confrm.setCellData(i, "TRANSTR_EMP_NO", js_emp_no);
    }
    scwin.gLastJob = "저장";
    trs_SaveConfrmYn.Action = "/PersonOnDuty.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&EMP_NO=" + js_emp_no + "&method=modifyDutyConfmYn";
    trs_SaveConfrmYn.KeyName = "toinb_dataid4";
    trs_SaveConfrmYn.KeyValue = "JSP(I:pInput=dts_Confrm)";
    trs_SaveConfrmYn.Post();
};
scwin.fn_SaveAttachFile = function() {
    var url = "/PersonOnDuty.do?method=saveDutyDiaryAttachFile" + "&CONFRM_DD=" + scwin.gSearchDay + "&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Update.Action = url;
    trs_Update.KeyValue = "JSP(I:pFile=dts_fileList)";
    trs_Update.Post();
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인해 주세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength3 = function(text, size, lbl) {
    var overLen = eval($c.stf.getStringSize(text) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인해 주세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return false;
    }
    return true;
};
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_filedown = function(contn_id, attach_seq) {
    location.href = "/filedownload.do?file_id=" + contn_id + "&attach_seq=" + attach_seq + "&gubun=45";
};
scwin.fn_validDateTodayCheck = function() {
    if ($c.stf.getObjectValue(edt_Date) != scwin.fn_getToday()) {
        $c.win.alert("저장할 수 없습니다.\n[반영일]을 확인해 주세요.");
        edt_Date.focus();
        return false;
    }
    return true;
};
scwin.fn_validDateCheck = function() {
    if (Number($c.stf.getObjectValue(edt_Date)) < Number(scwin.fn_getToday())) {
        $c.win.alert("저장할 수 없습니다.\n[반영일]을 확인해 주세요.");
        edt_Date.focus();
        return false;
    }
    return true;
};
scwin.fn_validConfrmCheck = function() {
    var err_row = 0;
    var err_col = 0;
    for (var i = 1; i <= dts_Confrm.getTotalRow(); i++) {
        for (var j = 1; j <= 2; j++) {
            if (dts_Confrm.getCellData(i, "CONFRM_SEQ" + j) != '') {
                if (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN" + j) != 'Y') {
                    err_row = i;
                    err_col = j;
                    i = dts_Confrm.getTotalRow() + 1;
                    j = 3;
                }
            }
        }
    }
    if (err_row > 0) {
        dts_Confrm.setRowPosition(err_row, 0);
        $c.win.alert("당번 확인이 완료되지 않았습니다.\n[당번 확인사항]을 확인해 주세요.");
        grd_List2.SetColumn("DUTY_CONFRM_YN" + err_col);
        grd_List2.focus();
        return false;
    }
    return true;
};
scwin.fn_validCheck = function() {
    if ($c.stf.getObjectValue(edt_Date) == "") {
        $c.win.alert("[반영일]을 입력하세요.");
        edt_Date.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DIARY_TP_CD) == "") {
        $c.win.alert("[구분]을 입력하세요.");
        cmb_DIARY_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_isur_cd) == "") {
        $c.win.alert("[종목코드]를 입력하세요.");
        txb_isur_cd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CONTN) == "") {
        $c.win.alert("[내용]을 입력하세요.");
        txb_CONTN.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_REF_CONTN) == "") {
    	alert("[참고사항]을 입력하세요.");
    	txb_REF_CONTN.focus();
    	return false;
    }
    */
    if ($c.stf.getObjectValue(cmb_DEP_CD) == "") {
        $c.win.alert("[팀]을 입력하세요.");
        cmb_DEP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_EMP_NO) == "") {
        $c.win.alert("[조치자]를 입력하세요.");
        cmb_EMP_NO.focus();
        return false;
    }
    if (!scwin.checkMaxLength1(txb_CONTN, 200, "내용")) {
        $c.stf.setObjectValue(txb_CONTN, "");
        txb_CONTN.focus();
        return false;
    }
    if (!scwin.checkMaxLength1(txb_REF_CONTN, 200, "참고사항")) {
        $c.stf.setObjectValue(txb_REF_CONTN, "");
        txb_CONTN.focus();
        return false;
    }
    return true;
};
scwin.fn_setSaveHeader = function() {
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUTYDIARY_MKTACT_IN";
    dts_MASTER.Reset();
    dts_MASTER.insertRow();
    dts_UpdateProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUTYDIARY_PROCS_STAT_INOUT";
    dts_UpdateProcs.reset();
    dts_UpdateProcs.insertRow();
    dts_DeleteDiary.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUTYDIARY_MKTACT_LIST_INOUT";
    dts_DeleteDiary.reset();
    dts_DeleteDiary.insertRow();
};
scwin.fn_SetHeader = function() {
    scwin.fn_setSaveHeader();
};
scwin.fn_ReadProcsStat = function() {
    var url = "/PersonOnDuty.do?method=readDutyDiaryProcsStat" + "&CONFRM_DD=" + scwin.gSearchDay + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.Action = encodeURI(url);
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_Procs,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_ListConfrmItm = function() {
    $c.cm.ShowWin(grd_List2);

    //dts_Confrm.ClearData();

    var url = "/PersonOnDuty.do?method=listDutyDiaryConfrmItm" + "&CONFRM_DD=" + scwin.gSearchDay + "&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Confrm.DataID = encodeURI(url);
    dts_Confrm.Reset();
};
scwin.fn_ListMktactDtl = function() {
    $c.cm.ShowWin(grd_List);
    var url = "/PersonOnDuty.do?method=listDutyDiaryMktactDtl" + "&CONFRM_DD=" + scwin.gSearchDay + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Diary.DataID = encodeURI(url);
    dts_Diary.Reset();
};
scwin.fn_Search = function() {
    if ($c.stf.getObjectValue(edt_Date) == "") {
        $c.win.alert("[반영일]을 입력하세요.");
        edt_Date.focus();
        return false;
    }
    scwin.gStatTp = 9;
    scwin.gToday = scwin.fn_getToday();
    scwin.gSearchDay = $c.stf.getObjectValue(edt_Date);

    //파일첨부 초기화
    dts_fileList.removeAll();

    //당번확인사항 조회
    scwin.fn_ListConfrmItm();

    //시장조치사항 조회
    scwin.fn_ListMktactDtl();
};
scwin.fn_delete = function(row, colid) {
    var res = window.confirm("삭제하시겠습니까?");
    if (scwin.fn_validDateCheck() && res) {
        scwin.gLastJob = "삭제";
        /*
        var url = "/PersonOnDuty.do?method=deleteDutyDiaryMktactDtl";
        	url += "&CONFRM_DD=" + dts_Diary.NameString(row, "CONFRM_DD");
        	url += "&DIARY_SEQ=" + dts_Diary.NameString(row, "DIARY_SEQ");
        	url += "&TRANSTR_EMP_NO=" + js_emp_no;
        	url += "&SCREN_ID=" + vScrenID;
        	url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;

        dts_Diary.DataID = encodeURI(url);
        dts_Diary.Reset();
        */
        var sCONFRM_DD = dts_Diary.getCellData(row, "CONFRM_DD");
        var sDIARY_SEQ = dts_Diary.getCellData(row, "DIARY_SEQ");
        dts_DeleteDiary.setCellData(1, "CONFRM_DD", sCONFRM_DD);
        dts_DeleteDiary.setCellData(1, "DIARY_SEQ", sDIARY_SEQ);
        dts_DeleteDiary.setCellData(1, "EMP_NO", js_emp_no);
        scwin.gLastJob = "삭제";
        //trs_DeleteDiary.Action = "/PersonOnDuty.do?method=deleteDutyDiaryMktactDtl&CONFRM_DD=" + sCONFRM_DD + "&DIARY_SEQ=" + sDIARY_SEQ + "&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
