//수정권한 설정
scwin.fn_SetModifyAuth = function() {
    //alert(getObjectValue(edt_Date) + "\n" + fn_getToday());
    //오늘날짜  버튼 비활성화
    if (Number($c.stf.getObjectValue(edt_Date)) < Number(scwin.fn_getToday())) {
        scwin.fn_SetDisable();
    } else if (Number($c.stf.getObjectValue(edt_Date)) > Number(scwin.fn_getToday())) {
        //1,2차 검토 && 승인, 취소
        scwin.fn_SetDisable1();
        scwin.fn_SetDisable1_1();

        //시장조치
        scwin.fn_SetEnable2();

        //당번 확인사항 && 파일첨부
        if (scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {
            scwin.fn_SetEnable3();
            scwin.fn_SetEnable4();
        }
    } else {
        //alert(gDutyYn + "\n" + gDutyChrg + "\n" + gStatTp);
        //1,2차 검토
        if ((scwin.gDutyYn != 'Y' || scwin.gStatTp > 2) && (scwin.gDutyChrg != 'Y' || scwin.gStatTp != 3)) {
            //당번
            scwin.fn_SetDisable1();
        }

        //승인
        //if(gDutyChrg != 'Y' || gStatTp != 3) {		//당번팀장
        //	fn_SetDisable1();
        //}

        //취소
        if (scwin.gDutyYn != 'Y' && scwin.gDutyChrg != 'Y') {
            scwin.fn_SetDisable1_1();
        }

        //시장조치
        if (scwin.gStatTp > 2) {
            //2차검토 후 시장조치 입력불가
            scwin.fn_SetDisable2();
        } else {
            scwin.fn_SetEnable2();
        }

        //당번 확인사항
        if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && scwin.gStatTp == 1) {
            scwin.fn_SetEnable3();
        } else {
            scwin.fn_SetDisable3();
        }

        //파일첨부
        if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && scwin.gStatTp != 9) {
            scwin.fn_SetEnable4();
        } else {
            scwin.fn_SetDisable4();
        }
    }
};
scwin.fn_btnPrint = function() {
    if (scwin.gStatTp != 9) {
        $c.win.alert("승인 처리가 되지 않았습니다.");
        return;
    }
    scwin.fn_print_pdf();
};
scwin.fn_print_pdf = function() {
    var pdf_rptname = "RLDSTF41010";
    var confrm_dd = scwin.gSearchDay.substring(0, 4) + "-" + scwin.gSearchDay.substring(4, 6) + "-" + scwin.gSearchDay.substring(6, 8);
    var tbl1 = "";
    for (var i = 1; i <= dts_Diary.getTotalRow(); i++) {
        tbl1 += "<tr>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "DEP_NM") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "EMP_NM") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "COM_ABBRV") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_TP_NM") + "</td>";
        tbl1 += "		<td style='text-align: left;'>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_CONTN") + "</td>";
        tbl1 += "		<td style='text-align: left;'>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_REF_CONTN") + "</td>";
        tbl1 += "</tr>";
    }
    var tbl2 = "";
    for (var i = 1; i <= dts_Confrm.getTotalRow(); i++) {
        tbl2 += "<tr>";
        tbl2 += "		<td>" + dts_Confrm.getCellData(i, "DUTY_CONFRM_ITM_NM1") + "</td>";
        tbl2 += "		<td>" + (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN1") == 'Y' ? '예' : '아니오') + "</td>";
        tbl2 += "		<td>" + dts_Confrm.getCellData(i, "DUTY_CONFRM_ITM_NM2") + "</td>";
        tbl2 += "		<td>" + (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN2") == 'Y' ? '예' : '') + "</td>";
        tbl2 += "</tr>";
    }
    var userParam = [{
        uid: "CONFRM_DD",
        unm: confrm_dd
    }, {
        uid: "MSG1",
        unm: dts_Procs.getCellData(1, "MSG1")
    }, {
        uid: "MSG2",
        unm: dts_Procs.getCellData(1, "MSG2")
    }, {
        uid: "MSG3",
        unm: dts_Procs.getCellData(1, "MSG4")
    }, {
        uid: "TBL1",
        unm: tbl1
    }, {
        uid: "TBL2",
        unm: tbl2
    }, {
        uid: "print_time",
        unm: ''
    }];
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
};

