scwin.fn_com_grid_pos_ex = function(grdObj, grdObj2) {
    js_com_Isurcd = grdObj; //발행사코드
    js_com_Isurnm = grdObj2; //발행사명
    scwin.IsurTagetPos_ex(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = js_com_left;
    Grd_com_isur.style.top = js_com_top;
};
scwin.IsurTagetPos_ex = function(grdObj, grdObj2, Tg) {
    var cL = 7;
    var cT = 53;
    if (Tg == "G") {
        cL = 49;
        cT = 0;
    }
    js_com_left = grdObj.style.left;
    js_com_left = js_com_left.substring(0, js_com_left.length - 2);
    js_com_left = eval(js_com_left) + cL;
    js_com_top = grdObj.style.top;
    js_com_top = js_com_top.substring(0, js_com_top.length - 2);
    js_com_top = eval(js_com_top) + cT;
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
