};
scwin.dts_EMP_NO_OnFilter = function(row) {
    /*
    	if(row == 5) {
    		alert(dts_EMP_NO.NameString(row, "TEXT"));
    	}
    */
    //  부서코드에  해당하는 사원을 가져온다.
    var vVal = $c.stf.getObjectValue(cmb_DEP_CD);
    if (vVal == "") {
        // 전체일 경우
        return true;
    } else {
        var vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 == "") return true; // 전체.
        return (vVal == vVal2) ? true : false;
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
