scwin.btn_SaveConfrm_onclick = function() {
    var k = 0;
    for (var i = 1; i <= dts_Confrm.getTotalRow(); i++) {
        if (dts_Confrm.getRowStatus(i) == '3') {
            k++;
        }
    }
    if (k == 0) {
        $c.win.alert("변경사항이 없습니다.");

        // 목록 다시 조회
        scwin.fn_ListConfrmItm();
    } else {
        scwin.fn_SaveConfrm();
    }
};
